import heapq


def _interval_solver(data, capacity, largest):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    if mandatory & blocked or len(mandatory) > k:
        return {"error": "impossible"}
    options = [job for job in jobs if job["id"] not in blocked]
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None

    for subset in combinations(options, k):
        ids = tuple(sorted(job["id"] for job in subset))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        active = []
        valid = True
        for job in sorted(subset, key=lambda x: (x["start"], x["end"], x["id"])):
            active = [end for end in active if end > job["start"]]
            active.append(job["end"])
            if len(active) > capacity:
                valid = False
                break
        if not valid:
            continue
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value or
                (value == best_value and
                 (ids > best_ids if largest else ids < best_ids))):
            best_value, best_ids = value, ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _build_interval(capacity, largest):
    return lambda data: _interval_solver(data, capacity, largest)


def _build_ledger():
    def rounded(numerator, mode):
        if mode == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (sequence, event.get("revision", 0), position)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), mode)
            tax = rounded(net * event.get("tax_bp", 0), mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = (event.get("account", "default") + "|" +
                   event.get("currency", "USD"))
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_resolver():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        roots = data["roots"]
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        best_vector = None
        best_result = None

        def acyclic(edges):
            visiting, done = set(), set()

            def visit(name):
                if name in visiting:
                    return False
                if name in done:
                    return True
                visiting.add(name)
                if any(not visit(other) for other in edges.get(name, [])):
                    return False
                visiting.remove(name)
                done.add(name)
                return True

            return all(visit(name) for name in edges)

        def search(versions, bounds, reached, processed, edges):
            nonlocal best_vector, best_result
            pending = sorted(reached - processed)
            if not pending:
                if not acyclic(edges):
                    return
                vector = tuple(versions.get(name, -1) for name in names)
                if best_vector is None or vector > best_vector:
                    best_vector = vector
                    best_result = {"versions": dict(versions)}
                return

            name = pending[0]
            low, high = bounds[name]
            candidates = [row for row in packages[name]
                          if low <= row["version"] <= high
                          and row["version"] not in blocked.get(name, [])
                          and (name not in pins or row["version"] == pins[name])]
            candidates.sort(key=lambda row: row["version"], reverse=True)
            for row in candidates:
                version = row["version"]
                next_versions = dict(versions)
                next_versions[name] = version
                next_bounds = dict(bounds)
                next_reached = set(reached)
                next_processed = set(processed)
                next_edges = {key: list(value) for key, value in edges.items()}
                next_processed.add(name)
                active = [dep for dep in row.get("deps", [])
                          if not dep.get("feature") or dep.get("feature") in features]
                next_edges[name] = [dep["name"] for dep in active]
                valid = True
                for dep in active:
                    target = dep["name"]
                    dep_low, dep_high = dep["min"], dep["max"]
                    if target in next_bounds:
                        old_low, old_high = next_bounds[target]
                        dep_low, dep_high = max(old_low, dep_low), min(old_high, dep_high)
                    if dep_low > dep_high:
                        valid = False
                        break
                    next_bounds[target] = (dep_low, dep_high)
                    next_reached.add(target)
                    if target in next_versions and not dep_low <= next_versions[target] <= dep_high:
                        valid = False
                        break
                if valid:
                    search(next_versions, next_bounds, next_reached,
                           next_processed, next_edges)

        initial_bounds = {name: tuple(bounds) for name, bounds in roots.items()}
        search({}, initial_bounds, set(roots), set(), {})
        return best_result if best_result is not None else {"error": "unsatisfiable"}

    return solve


def _build_routes():
    def solve(data):
        required = data.get("required", [])
        bit_for = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        start_node = data["source"]
        start_mask = bit_for.get(start_node, 0)
        coupons = data["coupons"]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        start = data["start"]
        distances = {(start_node, start_mask, 0): start}
        queue = [(start, start_node, start_mask, 0)]
        while queue:
            time, node, mask, used = heapq.heappop(queue)
            state = (node, mask, used)
            if distances.get(state) != time:
                continue
            if node == data["target"] and mask == full and used == coupons:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], used)]
                if used < coupons:
                    reduced = max(2, edge["duration"] - edge.get("discount", 0))
                    options.append((reduced, used + 1))
                next_node = edge["v"]
                next_mask = mask | bit_for.get(next_node, 0)
                for duration, next_used in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_state = (next_node, next_mask, next_used)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, next_node, next_mask, next_used))
        return {"arrival": None}
    return solve


